    #[test]
    fn test_add_basic_positive_integers() {
      // If the inputs are positive integers (e.g., 1 and 2), then the function should return their mathematical sum (3). This verifies the core 'sum of a and b' requirement for standard positive cases.
      assert_eq!(add(1, 2), 3);
    }

    #[test]
    fn test_add_basic_negative_integers() {
      // If the inputs are negative integers (e.g., -1 and -2), then the function should return their mathematical sum (-3). This ensures correct handling of negative values.
      assert_eq!(add(-1, -2), -3);
    }

    #[test]
    fn test_add_mixed_signs_result_positive() {
      // If the inputs have mixed signs and the positive magnitude is larger (e.g., -5 and 10), then the function should return the correct positive sum (5). This verifies subtraction logic within addition.
      assert_eq!(add(-5, 10), 5);
    }

    #[test]
    fn test_add_mixed_signs_result_negative() {
      // If the inputs have mixed signs and the negative magnitude is larger (e.g., 5 and -10), then the function should return the correct negative sum (-5). This verifies subtraction logic within addition.
      assert_eq!(add(5, -10), -5);
    }

    #[test]
    fn test_add_zero_identity_left() {
      // If the first argument is zero (e.g., 0 and 5), then the function should return the second argument (5). This tests the additive identity property.
      assert_eq!(add(0, 5), 5);
    }

    #[test]
    fn test_add_zero_identity_right() {
      // If the second argument is zero (e.g., 5 and 0), then the function should return the first argument (5). This tests the additive identity property.
      assert_eq!(add(5, 0), 5);
    }

    #[test]
    fn test_add_both_zeros() {
      // If both arguments are zero (0 and 0), then the function should return 0. This is a minimal edge case for the additive identity.
      assert_eq!(add(0, 0), 0);
    }

    #[test]
    fn test_add_near_max_boundary() {
      // If the inputs are near the i32 maximum but do not overflow (e.g., i32::MAX - 1 and 1), then the function should return i32::MAX. This verifies correctness at the upper boundary of the type range.
      assert_eq!(add(i32::MAX - 1, 1), i32::MAX);
    }

    #[test]
    fn test_add_near_min_boundary() {
      // If the inputs are near the i32 minimum but do not underflow (e.g., i32::MIN + 1 and -1), then the function should return i32::MIN. This verifies correctness at the lower boundary of the type range.
      assert_eq!(add(i32::MIN + 1, -1), i32::MIN);
    }
